mapper.select:
SELECT p.category AS category, NULL AS supplyPointName, COALESCE(SUM(CASE WHEN r.type = 'out' THEN r.quantity ELSE 0 END), 0) AS outgoingQuantity, COALESCE(AVG(p.stock_quantity), 0) AS averageStock, #{period} AS period FROM spare_part p LEFT JOIN stock_record r ON p.id = r.part_id AND r.operate_time >= #{startDate} AND r.operate_time < #{endDate} WHERE p.category IS NOT NULL
AND p.supply_point_id = #{supplyPointId}
GROUP BY p.category ORDER BY outgoingQuantity DESC

SELECT NULL AS category, s.name AS supplyPointName, COALESCE(SUM(CASE WHEN r.type = 'out' THEN r.quantity ELSE 0 END), 0) AS outgoingQuantity, COALESCE(AVG(p.stock_quantity), 0) AS averageStock, #{period} AS period FROM spare_part p LEFT JOIN supply_point s ON p.supply_point_id = s.id LEFT JOIN stock_record r ON p.id = r.part_id AND r.operate_time >= #{startDate} AND r.operate_time < #{endDate}
WHERE p.category = #{category}
GROUP BY s.name ORDER BY outgoingQuantity DESC

SELECT FORMATDATETIME(r.operate_time, 'yyyy-MM') AS "month", p.category AS category, COALESCE(SUM(CASE WHEN r.type = 'in' THEN r.quantity ELSE 0 END), 0) AS stockInQuantity, COALESCE(SUM(CASE WHEN r.type = 'out' THEN r.quantity ELSE 0 END), 0) AS stockOutQuantity, COALESCE( SUM(CASE WHEN r.type = 'in' THEN r.quantity ELSE 0 END) - SUM(CASE WHEN r.type = 'out' THEN r.quantity ELSE 0 END), 0 ) AS netChange FROM stock_record r LEFT JOIN spare_part p ON r.part_id = p.id WHERE r.operate_time >= #{startDate} AND r.operate_time < #{endDate}
AND p.category = #{category}
AND p.supply_point_id = #{supplyPointId}
GROUP BY FORMATDATETIME(r.operate_time, 'yyyy-MM'), p.category ORDER BY "month" DESC

SELECT COALESCE(
    SUM(CASE WHEN r.type = 'out' THEN r.quantity ELSE 0 END) * 1.0 /
    NULLIF(AVG(p.stock_quantity), 0),
    0
)
FROM spare_part p
LEFT JOIN stock_record r ON p.id = r.part_id
    AND r.operate_time >= #{startDate}
    AND r.operate_time < #{endDate}
WHERE p.stock_quantity > 0
